//   ponto de vista daquele trecho, como a etiqueta na porta do quarto.
// - "***" sozinho numa linha = divisor de cena.
// - notaInicio / notaFim (opcionais): notas da autora, aparecem como bilhetes.
// - Não use o caractere ` (crase sozinha) dentro do texto.
// =====================================================================

